-- Greece: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'gr-mydata-mandatory', id, '2021-01-01', 1, 'https://www.aade.gr/mydata', 0, '[{"label": "AADE — myDATA", "url": "https://www.aade.gr/mydata"}]', NULL FROM countries WHERE code = 'GR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-mydata-mandatory', 'en', 'myDATA real-time reporting becomes mandatory', 'AADE''s myDATA (My Digital Accounting and Tax Application) platform becomes mandatory for all Greek taxpayers, requiring real-time or near real-time transmission of invoice and bookkeeping data. Every transaction receives a unique registration mark (MARK) and QR code from AADE — the reporting backbone every later e-invoicing layer builds on.', '["Register for myDATA reporting via AADE''s portal or a certified ERP/accounting integration", "Confirm your systems generate the MARK and QR code correctly for every invoice"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'gr-b2g-2025', id, '2025-09-01', 0, 'https://www.theinvoicinghub.com/einvoicing-compliance-greece/', 1, '[{"label": "AADE — myDATA", "url": "https://www.aade.gr/mydata"}]', NULL FROM countries WHERE code = 'GR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2g-2025', 'en', 'B2G e-invoicing fully mandatory', 'Following a phased rollout across public administrations from September 2023, B2G e-invoicing becomes fully mandatory for all public contracts exceeding €2,500. Suppliers submit EN 16931-compliant invoices (Greek Peppol CIUS) for myDATA validation and MARK assignment, then transmission via accredited Peppol Access Points to the National Interoperability Center (KED).', '["Confirm your Peppol Access Point is accredited for the Greek CIUS", "Check whether your specific public-sector counterparty is within the €2,500 contract threshold"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'gr-b2b-phase1-2026', id, '2026-03-02', 0, 'https://www.vatcalc.com/greece/greece-mydata-e-book-and-e-invoices-update/', 1, '[{"label": "AADE — myDATA", "url": "https://www.aade.gr/mydata"}]', NULL FROM countries WHERE code = 'GR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase1-2026', 'en', 'Domestic B2B e-invoicing mandate — Phase 1 begins', 'Structured B2B e-invoicing becomes mandatory for businesses with annual revenue above €1 million, under an EU derogation (Council Implementing Decision (EU) 2025/502) authorising Greece to depart from Articles 218 and 232 of the VAT Directive. Invoices are validated through the myDATA clearance system before exchange. A graduated-enforcement transition period ran through 3 May 2026, during which isolated technical failures did not trigger the full penalty framework.', '["Confirm your invoicing solution supports myDATA clearance for domestic B2B", "Check whether your annual revenue places you in this first phase, or the October 2026 second phase"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'gr-b2b-phase2-2026', id, '2026-10-01', 0, 'https://rtcsuite.com/e-invoicing-greece/', 1, '[{"label": "AADE — myDATA", "url": "https://www.aade.gr/mydata"}]', NULL FROM countries WHERE code = 'GR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-b2b-phase2-2026', 'en', 'Domestic B2B mandate extends to all remaining businesses', 'The domestic B2B e-invoicing mandate extends to every remaining Greek business, with an adjustment period through 31 December 2026. The obligation covers domestic B2B transactions and B2B sales to non-EU entities; intra-EU B2B e-invoicing remains optional for now. Compliance routes include certified e-invoicing providers, AADE''s free ''Timologio'' app, or direct ERP integration via the myDATA REST API.', '["Confirm your compliance route (certified provider, Timologio, or direct API integration) well before the deadline", "Note that intra-EU B2B invoicing is not yet mandated — only domestic and non-EU B2B"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'gr-vida-2030', id, '2030-07-01', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en', 1, '[{"label": "AADE — myDATA", "url": "https://www.aade.gr/mydata"}]', NULL FROM countries WHERE code = 'GR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gr-vida-2030', 'en', 'ViDA cross-border B2B digital reporting takes effect', 'Regardless of the domestic mandate''s own scope and timeline, the EU''s VAT in the Digital Age (ViDA) directive requires structured e-invoicing and digital reporting for cross-border B2B transactions from 1 July 2030 — confirmed EU law (Council Directive (EU) 2025/516).', '["Businesses trading cross-border within the EU should plan for EN 16931-compliant e-invoicing and reporting capability by this date"]');
